        StructuredSubQuestion("(ii)", "ඉලෙක්ට්‍රොනික වින්‍යාසය (Electronic Configuration) යනු කුමක්ද?", 4, "පරමාණුවක ශක්ති මට්ටම් වටා ඉලෙක්ට්‍රෝන ව්‍යාප්ත වී ඇති ආකාරය.", listOf("ඉලෙක්ට්‍රොනික වින්‍යාසය (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "ආවර්තිතා වගුවේ කාණ්ඩයක් (Group) සහ ආවර්තයක් (Period) හඳුනාගන්නේ කෙසේද?", 4, "පිටත ශක්ති මට්ටමේ ඉලෙක්ට්‍රෝන ගණනින් කාණ්ඩයත්, මුළු ශක්ති මට්ටම් ගණනින් ආවර්තයත් තීරණය වේ.", listOf("ආවර්තිතා වගුව (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "සමස්ථානික (Isotopes) යන්නෙහි තේරුම ලියන්න.", 4, "එකම පරමාණුක ක්‍රමාංකය ඇති නමුත් වෙනස් ස්කන්ධ ක්‍රමාංක සහිත පරමාණු.", listOf("සමස්ථානික (ලකුණු 4)"))
      )
      else -> listOf(
        StructuredSubQuestion("(i)", "$theme හා සම්බන්ධ නූතන විද්‍යාත්මක සොයාගැනීමක් හෝ තාක්ෂණයක් නම් කරන්න.", 3, "නැනෝ තාක්ෂණය, අභ්‍යවකාශ ගවේෂණය හෝ AI තාක්ෂණය.", listOf("නූතන සොයාගැනීම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම තාක්ෂණය මිනිසාගේ දෛනික ජීවිතයට බලපා ඇති ආකාරය ලියන්න.", 4, "කාර්යයන් පහසු වීම, සන්නිවේදන වේගය වැඩි වීම සහ සෞඛ්‍ය පහසුකම් දියුණු වීම.", listOf("ප්‍රායෝගික බලපෑම (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "විද්‍යාත්මක දැනුම සදාචාරාත්මකව (Ethically) භාවිත කිරීමේ වැදගත්කම පැහැදිලි කරන්න.", 4, "අනිසි භාවිතයෙන් සිදුවන විනාශයන් (උදා: අවි ආයුධ) වළක්වා ගෙන මානව හිතවාදීව යොදා ගැනීම.", listOf("සදාචාරාත්මක භාවිතය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "අනාගත විද්‍යාත්මක ලෝකය ගැන ඔබේ අදහස දක්වන්න.", 4, "තිරසාර සම්පත් භාවිතය සහ අන්තර් ග්‍රහලෝක සබඳතා වැනි ක්ෂේත්‍රවල ප්‍රගතිය.", listOf("අනාගත දැක්ම (ලකුණු 4)"))
      )
    }
  }


  // =================================================================================
  // 2. MATHEMATICS (ගණිතය)
  // =================================================================================
  private fun getMathSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    
    // Technical Facts for Math (O/L Curriculum)
    val techFacts = when {
      theme.contains("සංඛ්‍යා රටා") || theme.contains("ශ්‍රේඪි") -> Triple("Tn = a + (n-1)d", "Sn = n/2 [2a + (n-1)d]", "a=පළමු පදය, d=පොදු අන්තරය/අනුපාතය")
      theme.contains("වීජ") || theme.contains("සාධක") -> Triple("(a+b)(a-b) = a²-b²", "x = [-b ± √(b²-4ac)] / 2a", "ax² + bx + c = 0")
      theme.contains("සමීකරණ") -> Triple("ax + by = c", "ඡේදන ලක්ෂ්‍යය (x, y)", "විචල්‍යයක් ඉවත් කිරීමේ ක්‍රමය")
      theme.contains("දර්ශක") || theme.contains("ලඝු") -> Triple("aᵐ × aⁿ = aᵐ⁺ⁿ", "logₐ x + logₐ y = logₐ (xy)", "10⁰ = 1 සහ log 1 = 0")
      theme.contains("පරිමිතිය") || theme.contains("වර්ගඵලය") -> Triple("වෘත්තය: 2πr සහ πr²", "ත්‍රපීසියමය: ½(a+b)h", "සිලින්ඩරය: 2πrh + 2πr²")
      theme.contains("ජ්‍යාමිතිය") || theme.contains("ප්‍රමේය") -> Triple("ත්‍රිකෝණයක අභ්‍යන්තර කෝණ එකතුව 180°", "පයිතගරස් ප්‍රමේයය: a² + b² = c²", "සමාන්තරාස්‍රයක සම්මුඛ කෝණ සමානයි")
      theme.contains("සංඛ්‍යානය") || theme.contains("මධ්‍යන්‍ය") -> Triple("මධ්‍යන්‍යය = Σfx / Σf", "මධ්‍යස්ථය = (n+1)/2 වන පදය", "පන්ති ප්‍රාන්තර මධ්‍ය අගය")
      theme.contains("සම්භාවිතාව") -> Triple("P(A) = n(A) / n(S)", "P(A') = 1 - P(A)", "ස්වාධීන සිදුවීම්: P(A∩B) = P(A)×P(B)")
      theme.contains("ත්‍රිකෝණමිතිය") -> Triple("sin θ = සම්මුඛ / කර්ණය", "cos θ = බද්ධ / කර්ණය", "tan θ = සම්මුඛ / බද්ධ")
      theme.contains("වාණිජ") || theme.contains("පොලී") -> Triple("I = PRT / 100", "වැල් පොලී: A = P(1 + r/100)ⁿ", "බදු = වටිනාකම × බදු ප්‍රතිශතය")
      else -> Triple("$theme මූලික සූත්‍රය", "පියවරෙන් පියවර සුළු කිරීම", "නිවැරදි ඒකක සහිත අවසාන පිළිතුර")
    }

    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) සංඛ්‍යා රටාවේ පළමු පදය a = 5 සහ පොදු වෙනස d = 4 නම් n වන පදය Tn සොයන්න.", 3, "Tn = 4n + 1", listOf("Tn = 4n + 1")),
        StructuredSubQuestion("(ii)", "එම සමාන්තර ශ්‍රේඪියේ 25 වන පදය T25 ගණනය කරන්න.", 4, "T25 = 101", listOf("T25 = 101")),
        StructuredSubQuestion("(iii)", "පළමු පද 10යේ එකතුව S10 සොයන්න.", 4, "S10 = 230", listOf("S10 = 230")),
        StructuredSubQuestion("(iv)", "මෙම රටාවේ 161 ලබාදෙන්නේ කීවෙනි පදයෙන්දැයි සොයන්න.", 4, "n = 40", listOf("n = 40")),
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "(3x + 2)(2x + 5) ප්‍රසාරණය කර සුළු කරන්න.", 3, "6x² + 19x + 10", listOf("6x² + 19x + 10")),
        StructuredSubQuestion("(ii)", "4x² - 25y² සාධක වෙන් කරන්න.", 4, "(2x - 5y)(2x + 5y)", listOf("(2x - 5y)(2x + 5y)")),
        StructuredSubQuestion("(iii)", "2x² + 7x + 6 සාධක සොයන්න.", 4, "(2x + 3)(x + 2)", listOf("(2x + 3)(x + 2)")),
        StructuredSubQuestion("(iv)", "x² - 7x + 12 = 0 වර්ගජ සමීකරණය විසඳන්න.", 4, "x = 3 හෝ x = 4", listOf("x = 3, 4"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "4x - 7 = 17 සරල ඒකජ සමීකරණය විසඳන්න.", 3, "x = 6", listOf("x = 6")),
        StructuredSubQuestion("(ii)", "2x + 3y = 12 සහ x + y = 5 සමගාමී සමීකරණ විසඳන්න.", 4, "x = 3, y = 2", listOf("x = 3, y = 2")),
        StructuredSubQuestion("(iii)", "පෑන් 2ක සහ පැන්සල් 3ක මිල රු. 70කි. පෑනක මිල පැන්සලක මිල මෙන් දෙගුණයක් නම් එකක මිල සොයන්න.", 4, "පෑන = රු. 20, පැන්සල = රු. 10", listOf("පෑන = රු. 20, පැන්සල = රු. 10")),
        StructuredSubQuestion("(iv)", "සමගාමී සමීකරණ ඡේදන ලක්ෂ්‍යය (3, 2) නම් x සහ y අගයන් ලියන්න.", 4, "x = 3, y = 2", listOf("x = 3, y = 2"))
      )
      4 -> listOf(
        StructuredSubQuestion("(i)", "3⁴ × 3² / 3³ දර්ශක නීති භාවිතයෙන් සුළු කරන්න.", 3, "27", listOf("27")),
        StructuredSubQuestion("(ii)", "log₃ 81 = 4 දර්ශක ස්වරූපයෙන් දක්වන්න.", 4, "3⁴ = 81", listOf("3⁴ = 81")),
        StructuredSubQuestion("(iii)", "log 4 + log 5 - log 2 එකම අගයක් ලෙස සුළු කරන්න.", 4, "1", listOf("1")),
        StructuredSubQuestion("(iv)", "√(100 × 0.25) අගය ලියන්න.", 4, "5", listOf("5"))
      )
      5 -> listOf(
        StructuredSubQuestion("(i)", "අරය 14 cm වූ වෘත්තයක පරිමිතිය සොයන්න. (π = 22/7)", 3, "88 cm", listOf("88 cm")),
        StructuredSubQuestion("(ii)", "එම වෘත්තයේ වර්ගඵලය ගණනය කරන්න.", 4, "616 cm²", listOf("616 cm²")),
        StructuredSubQuestion("(iii)", "සමාන්තර පාද 8 cm සහ 12 cm වූ ද, ලම්බ උස 5 cm වූ ද ත්‍රපීසියමක වර්ගඵලය සොයන්න.", 4, "50 cm²", listOf("50 cm²")),
        StructuredSubQuestion("(iv)", "පැත්තක දිග 10 cm වූ සමචතුරස්‍රයකින් 7 cm අරය ඇති වෘත්ත කාලක් ඉවත් කළ විට ඉතිරි වර්ගඵලය සොයන්න.", 4, "61.5 cm²", listOf("61.5 cm²"))
      )
