  private fun getHistorySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) අධ්‍යයනයට භාවිත වන ප්‍රධාන සාහිත්‍ය මූලාශ්‍ර 2ක් නම් කරන්න.", 3, "1. මහාවංශය / දීපවංශය.\n2. පූජාවලිය / රාජාවලිය / ඡූලවංශය.", listOf("සාහිත්‍ය මූලාශ්‍ර 2 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "මෙම යුගය තහවුරු කරන ප්‍රධාන පුරාවිද්‍යාත්මක මූලාශ්‍ර 2ක් ලියන්න.", 4, "1. සෙල්ලිපි (ලෙන් ලිපි/ටැම් ලිපි).\n2. කාසි, මැටි බඳුන් හා ගොඩනැගිලි අවශේෂ.", listOf("පුරාවිද්‍යා මූලාශ්‍ර 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පුරාවිද්‍යාත්මක මූලාශ්‍ර සාහිත්‍ය මූලාශ්‍රවලට වඩා විශ්වාසදායක වීමට හේතුව පැහැදිලි කරන්න.", 4, "සමකාලීනව නිර්මාණය වූ, පසුකාලීනව වෙනස් කළ නොහැකි භෞතික සාක්ෂි වන බැවින්.", listOf("විශ්වාසදායක බව (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "විදේශීය වාර්තාකරුවන්ගේ (උදා: පාහියන් හිමි, ඉබ්න් බතුතා) වාර්තාවල ඇති වැදගත්කම ලියන්න.", 4, "මෙරට සමාජීය, ආර්ථික හා දේශපාලනික තත්ත්වයන් අපක්ෂපාතීව සටහන් වී තිබීම.", listOf("විදේශ වාර්තා වැදගත්කම (ලකුණු 4)"))
