  private fun getIctSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "පරිගණක මධ්‍යම සැකසුම් ඒකකයේ (CPU) ප්‍රධාන කොටස් 2ක් නම් කරන්න.", 3, "1. ගණිතමය හා තර්කන ඒකකය (ALU).\n2. පාලන ඒකකය (CU) සහ රෙජිස්ටර (Registers).", listOf("ALU සහ CU (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "Primary Memory (RAM) සහ Secondary Storage (Hard Disk) අතර ප්‍රධාන වෙනස්කම් 2ක් දක්වන්න.", 4, "1. RAM යනු නාසනය වන (Volatile) මතකයකි; Hard Disk යනු ස්ථීර (Non-volatile) මතකයකි.\n2. RAM හි වේගය අධිකය.", listOf("මතක වෙනස්කම් 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පරිගණකයක යන්ත්‍ර චක්‍රයේ (Fetch-Decode-Execute) ක්‍රියාවලිය කෙටියෙන් විස්තර කරන්න.", 4, "මතකයෙන් උපදෙස් ලබාගැනීම (Fetch), ඒවා තේරුම් ගැනීම (Decode) සහ ක්‍රියාත්මක කිරීම (Execute).", listOf("යන්ත්‍ර චක්‍රය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "Solid State Drive (SSD) උපාංග HDD වලට වඩා කාර්යක්ෂම වීමට හේතු ලියන්න.", 4, "චලනය වන කොටස් නොමැති වීම, අධික දත්ත කියවීමේ/ලියවීමේ වේගය සහ අඩු බල පරිභෝජනය.", listOf("SSD කාර්යක්ෂමතාව (ලකුණු 4)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "දශමය 25 සංඛ්‍යාව ද්විමය (Binary) සංඛ්‍යාවක් බවට පරිවර්තනය කරන්න.", 3, "25 / 2 = 12 r 1, 12 / 2 = 6 r 0, 6 / 2 = 3 r 0, 3 / 2 = 1 r 1, 1 / 2 = 0 r 1 ⇒ 11001₂.", listOf("11001₂ (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "ද්විමය 1011₂ සංඛ්‍යාවේ දශමය අගය ගණනය කරන්න.", 4, "1×2³ + 0×2² + 1×2¹ + 1×2⁰ = 8 + 0 + 2 + 1 = 11₁₀.", listOf("11₁₀ (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "ෂඩ්දශමය (Hexadecimal) 1A₁₆ සංඛ්‍යාව ද්විමය සංඛ්‍යාවක් බවට හරවන්න.", 4, "1 = 0001₂, A = 1010₂ ⇒ 00011010₂ (11010₂).", listOf("11010₂ (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ASCII සහ Unicode දත්ත නිරූපණ ක්‍රම අතර වෙනස ලියන්න.", 4, "ASCII බිටු 7/8කින් අක්ෂර 128/256ක් නිරූපණය කරයි; Unicode බිටු 16/32කින් ලෝකයේ සියලු භාෂා නිරූපණය කරයි.", listOf("ASCII හා Unicode වෙනස (ලකුණු 4)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "AND, OR සහ NOT යන මූලික තාර්කික ද්වාරවල සත්‍යතා වගු සංකේත අඳින ආකාරය දක්වන්න.", 3, "AND: ප්‍රතිදානය 1 වන්නේ ආදාන සියල්ල 1 විටදීය. OR: ඕනෑම ආදානයක් 1 විට ප්‍රතිදානය 1 වේ.", listOf("තාර්කික ද්වාර ලක්ෂණ (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "NAND ද්වාරයක් භාවිතයෙන් NOT ද්වාරයක් සාදාගන්නා ආකාරය පැහැදිලි කරන්න.", 4, "NAND ද්වාරයේ ආදාන දෙකම එකට සම්බන්ධ කිරීමෙන් NOT ද්වාරයක් ලැබේ.", listOf("NAND මඟින් NOT (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "A, B ආදාන සහිත NOR ද්වාරයක ප්‍රතිදාන ප්‍රකාශනය Y = (A + B)' ලියා දක්වන්න.", 4, "Y = (A + B)' ප්‍රකාශනය ලියා සත්‍යතා වගුව පිරීම.", listOf("NOR ප්‍රකාශනය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "බූලීය ප්‍රකාශනය Y = A.B + A.B' සුළු කර පෙන්වන්න.", 4, "Y = A(B + B') = A(1) = A.", listOf("Y = A (ලකුණු 4)"))
      )
