  // =================================================================================
  // 7. ENGLISH
  // =================================================================================
  private fun getEnglishSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "Fill in the blanks with Present Simple or Present Continuous: \"She _______ (read) a book every day, but today she _______ (write) an essay.\"", 3, "reads, is writing", listOf("Grammar completion (3 marks)")),
        StructuredSubQuestion("(ii)", "Rewrite in Past Simple: \"They go to Kandy by train and visit the Temple of the Tooth.\"", 4, "They went to Kandy by train and visited the Temple of the Tooth.", listOf("Past tense conversion (4 marks)")),
        StructuredSubQuestion("(iii)", "Correct the Subject-Verb Agreement error: \"The list of items are on the teacher's table.\"", 4, "Correct: \"The list of items IS on the teacher's table.\"", listOf("Error correction (4 marks)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "Complete with prepositions (in, on, at, under): \"The meeting is _______ 9.00 AM _______ Monday _______ the main hall.\"", 3, "at, on, in", listOf("Prepositions (3 marks)")),
        StructuredSubQuestion("(ii)", "Combine using relative pronouns (who, which): \"I met a doctor. He treated my brother.\"", 4, "I met a doctor who treated my brother.", listOf("Relative clauses (4 marks)")),
        StructuredSubQuestion("(iii)", "Transform to Passive Voice: \"The chef prepares a delicious meal for the guests.\"", 4, "A delicious meal is prepared for the guests by the chef.", listOf("Passive voice (4 marks)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "Change to Indirect Speech: \"I am very tired,\" said Ravi.", 3, "Ravi said that he was very tired.", listOf("Reported speech (3 marks)")),
        StructuredSubQuestion("(ii)", "Identify the adjective and adverb in this sentence: \"The brave soldier fought the enemy courageously.\"", 4, "Adjective: brave, Adverb: courageously.", listOf("Parts of speech (4 marks)")),
        StructuredSubQuestion("(iii)", "Complete the conditional sentence: \"If it rains, we _______ (stay) at home.\"", 4, "will stay", listOf("Conditional (4 marks)"))
      )
      4 -> listOf(
        StructuredSubQuestion("(i)", "Write the comparative and superlative forms of 'good' and 'heavy'.", 3, "good - better - best; heavy - heavier - heaviest.", listOf("Degrees of comparison (3 marks)")),
        StructuredSubQuestion("(ii)", "Punctuate correctly: \"have you seen my new book nimal asked\"", 4, "\"Have you seen my new book?\" Nimal asked.", listOf("Punctuation (4 marks)")),
        StructuredSubQuestion("(iii)", "Select the correct collective noun: \"A _______ of lions was seen in the forest.\"", 4, "pride", listOf("Collective nouns (4 marks)"))
      )
      5 -> listOf(
        StructuredSubQuestion("(i)", "Rearrange to form a question: \"you / did / where / go / yesterday / ?\"", 3, "Where did you go yesterday?", listOf("Question formation (3 marks)")),
        StructuredSubQuestion("(ii)", "Write the plural forms of: (a) leaf (b) child (c) ox.", 4, "(a) leaves (b) children (c) oxen.", listOf("Plurals (4 marks)")),
        StructuredSubQuestion("(iii)", "Complete the sentence using 'since' or 'for': \"I have been living here _______ ten years.\"", 4, "for", listOf("Prepositions of time (4 marks)"))
      )
      6 -> listOf(
        StructuredSubQuestion("(i)", "Identify the main idea of $theme ($grade Grade) in a single sentence.", 3, "Briefly stating the core concept of the unit in English.", listOf("Main idea (3 marks)")),
        StructuredSubQuestion("(ii)", "Give 2 synonyms and 2 antonyms for key words in this lesson.", 4, "Accurate vocabulary usage as per O/L standards.", listOf("Vocabulary (4 marks)")),
        StructuredSubQuestion("(iii)", "Write a short 4-line response expressing your opinion on this topic.", 4, "Grammatically correct and logical expression of thoughts.", listOf("Written expression (4 marks)"))
      )
      7 -> listOf(
        StructuredSubQuestion("(i)", "Choose the correct word: \"We _______ (won / one) the match and received _______ (won / one) trophy.\"", 3, "won, one", listOf("Homophones (3 marks)")),
        StructuredSubQuestion("(ii)", "Fill in with 'a', 'an' or 'the': \"He is _______ honest man and _______ best student in our class.\"", 4, "an, the", listOf("Articles (4 marks)")),
        StructuredSubQuestion("(iii)", "Change to Future Simple: \"She sings a song at the assembly.\"", 4, "She will sing a song at the assembly.", listOf("Tense conversion (4 marks)"))
      )
      8 -> listOf(
        StructuredSubQuestion("(i)", "Match the phrasal verbs with meanings: (a) Give up (b) Look for.", 3, "(a) Stop trying (b) Search.", listOf("Phrasal verbs (3 marks)")),
        StructuredSubQuestion("(ii)", "Combine using 'although': \"He is poor. He is very happy.\"", 4, "Although he is poor, he is very happy.", listOf("Conjunctions (4 marks)")),
        StructuredSubQuestion("(iii)", "Complete using 'used to': \"I _______ (play) cricket when I was young.\"", 4, "used to play", listOf("Past habits (4 marks)"))
      )
      9 -> listOf(
        StructuredSubQuestion("(i)", "Form a noun from the verb 'organize' and an adjective from 'beauty'.", 3, "Noun: organization, Adjective: beautiful.", listOf("Word formation (3 marks)")),
        StructuredSubQuestion("(ii)", "Identify the silent letter in: (a) knife (b) doubt (c) wrist.", 4, "(a) k (b) b (c) w.", listOf("Spelling (4 marks)")),
        StructuredSubQuestion("(iii)", "Write the opposite of: (a) visible (b) legal (c) happy.", 4, "(a) invisible (b) illegal (c) unhappy.", listOf("Prefixes (4 marks)"))
      )
      10 -> listOf(
        StructuredSubQuestion("(i)", "Complete the dialogue: A: \"Hello, how are you?\" B: \"_______.\"", 3, "I am fine, thank you. / Very well, thanks.", listOf("Dialogue (3 marks)")),
        StructuredSubQuestion("(ii)", "Give a formal greeting and an informal greeting.", 4, "Formal: Good morning. Informal: Hi / Hey.", listOf("Greetings (4 marks)")),
        StructuredSubQuestion("(iii)", "How do you ask for permission to enter a room?", 4, "May I come in, please?", listOf("Requests (4 marks)"))
      )
      11 -> listOf(
        StructuredSubQuestion("(i)", "Read a short paragraph and find a word that means 'very large'.", 3, "huge / enormous / gigantic (depending on text).", listOf("Reading skill (3 marks)")),
        StructuredSubQuestion("(ii)", "What is 'skimming' in reading comprehension?", 4, "Reading quickly to get the general idea or gist of the text.", listOf("Study skills (4 marks)")),
        StructuredSubQuestion("(iii)", "What is 'scanning' in reading comprehension?", 4, "Reading quickly to find specific information or facts.", listOf("Study skills (4 marks)"))
      )
      12 -> listOf(
        StructuredSubQuestion("(i)", "Write a formal letter head: Sender's address and Date.", 3, "Correct format: House No, Street, City, Date.", listOf("Letter writing (3 marks)")),
        StructuredSubQuestion("(ii)", "List 3 common phrases used in a formal letter ending.", 4, "Yours faithfully, Yours sincerely, Best regards.", listOf("Formal endings (4 marks)")),
        StructuredSubQuestion("(iii)", "Write a suitable salutation for a letter to a friend.", 4, "Dear [Name], / Dearest [Name],", listOf("Informal writing (4 marks)"))
      )
      13 -> listOf(
        StructuredSubQuestion("(i)", "What is a 'Compound Word'? Give an example.", 3, "A word made of two or more words. Example: Blackboard / Sunflower.", listOf("Vocabulary (3 marks)")),
        StructuredSubQuestion("(ii)", "Add a question tag: \"You are a student, _______?\"", 4, "aren't you?", listOf("Question tags (4 marks)")),
        StructuredSubQuestion("(iii)", "Add a question tag: \"She has finished her work, _______?\"", 4, "hasn't she?", listOf("Question tags (4 marks)"))
      )
      14 -> listOf(
        StructuredSubQuestion("(i)", "Convert the following statement into a request: \"Open the door.\"", 3, "Please open the door. / Could you please open the door?", listOf("Polite requests (3 marks)")),
        StructuredSubQuestion("(ii)", "Use 'neither...nor' to combine: \"I don't like tea. I don't like coffee.\"", 4, "I like neither tea nor coffee.", listOf("Correlative conjunctions (4 marks)")),
        StructuredSubQuestion("(iii)", "Use 'either...or' to combine: \"You can have a cake. You can have a biscuit.\"", 4, "You can have either a cake or a biscuit.", listOf("Correlative conjunctions (4 marks)"))
      )
      15 -> listOf(
        StructuredSubQuestion("(i)", "Identify the tense: \"We have been studying for three hours.\"", 3, "Present Perfect Continuous.", listOf("Tense identification (3 marks)")),
        StructuredSubQuestion("(ii)", "Correct the mistake: \"Every students must bring their books.\"", 4, "Correct: \"Every student must bring his/her book.\"", listOf("Grammar (4 marks)")),
        StructuredSubQuestion("(iii)", "Identify the tense: \"By next year, I will have finished my O/Ls.\"", 4, "Future Perfect.", listOf("Tense identification (4 marks)"))
      )
      16 -> listOf(
        StructuredSubQuestion("(i)", "What is an 'Idiom'? Give one example and its meaning.", 3, "A group of words with a special meaning. Example: Piece of cake (Very easy).", listOf("Idioms (3 marks)")),
        StructuredSubQuestion("(ii)", "Explain the idiom: 'Under the weather'.", 4, "Feeling sick or ill.", listOf("Idioms (4 marks)")),
        StructuredSubQuestion("(iii)", "Explain the idiom: 'Break a leg'.", 4, "Good luck.", listOf("Idioms (4 marks)"))
      )
      17 -> listOf(
        StructuredSubQuestion("(i)", "Define 'Alliteration' with an example.", 3, "Repetition of initial consonant sounds. Example: Six slippery snakes.", listOf("Poetry terms (3 marks)")),
        StructuredSubQuestion("(ii)", "Define 'Simile' with an example.", 4, "Comparing two things using 'as' or 'like'. Example: As brave as a lion.", listOf("Figures of speech (4 marks)")),
        StructuredSubQuestion("(iii)", "Define 'Metaphor' with an example.", 4, "Comparing two things by saying one IS the other. Example: He is a lion in the field.", listOf("Figures of speech (4 marks)"))
      )
      18 -> listOf(
        StructuredSubQuestion("(i)", "Form an adverb from 'happy' and 'fast'.", 3, "happily, fast (fast remains the same).", listOf("Adverbs (3 marks)")),
        StructuredSubQuestion("(ii)", "Complete using 'too' or 'enough': \"This box is _______ heavy to lift.\"", 4, "too", listOf("Adverbs of degree (4 marks)")),
        StructuredSubQuestion("(iii)", "Complete using 'too' or 'enough': \"He is old _______ to drive a car.\"", 4, "enough", listOf("Adverbs of degree (4 marks)"))
      )
      19 -> listOf(
        StructuredSubQuestion("(i)", "Identify the type of sentence: \"Alas! We lost the match.\"", 3, "Exclamatory sentence.", listOf("Sentence types (3 marks)")),
        StructuredSubQuestion("(ii)", "Identify the type of sentence: \"Stop talking and listen to me.\"", 4, "Imperative sentence.", listOf("Sentence types (4 marks)")),
        StructuredSubQuestion("(iii)", "Convert into an Interrogative sentence: \"He lives in Colombo.\"", 4, "Does he live in Colombo?", listOf("Sentence types (4 marks)"))
      )
      else -> listOf(
