  // =================================================================================
  // 9. CIVICS (පුරවැසි අධ්‍යාපනය)
  // =================================================================================
  private fun getCivicsSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    val wordingIdx = (setNumber + q) % 3

    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "පුරවැසියා යන්නෙහි අර්ථ දැක්වීම සහ යහපත් පුරවැසියෙකු සතු ප්‍රධාන ලක්ෂණයක් ලියන්න.", 3, "යම් රාජ්‍යයක නෛතික සාමාජිකත්වය දරන, අයිතිවාසිකම් හා යුතුකම් භුක්ති විඳින තැනැත්තා පුරවැසියා වේ.", listOf("පුරවැසි අර්ථය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "යහපත් පුරවැසියෙකු සතු විය යුතු සදාචාරාත්මක ගුණාංග 2ක් නම් කරන්න.", 4, "1. නීතියට ගරු කිරීම. 2. අන්‍යයන්ගේ අයිතිවාසිකම්වලට ගරු කිරීම සහ සහජීවනය.", listOf("ගුණාංග 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පුරවැසිභාවය අහිමි විය හැකි අවස්ථාවක් පෙන්වා දෙන්න.", 4, "රටට ද්‍රෝහී වීම, වෙනත් රටක පුරවැසිභාවය ලබාගැනීම හෝ නෛතික හේතූන් මත.", listOf("පුරවැසිභාවය අහිමි වීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ජාතික සංවර්ධනයට පුරවැසියෙකුගේ දායකත්වය වැදගත් වන්නේ ඇයි?", 4, "පුරවැසියාගේ ක්‍රියාකාරී දායකත්වයෙන් තොරව රටක ආර්ථික හා සමාජීය ස්ථාවරත්වය ගොඩනැගිය නොහැකි බැවින්.", listOf("ජාතික දායකත්වය (ලකුණු 4)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "ප්‍රජාතන්ත්‍රවාදය (Democracy) යන්නෙහි මූලික අර්ථය ලියා එහි ප්‍රධාන වර්ග 2 නම් කරන්න.", 3, "ජනතාවගේ පාලනයයි. වර්ග: ඍජු ප්‍රජාතන්ත්‍රවාදය සහ වක්‍ර (නියෝජිත) ප්‍රජාතන්ත්‍රවාදය.", listOf("ප්‍රජාතන්ත්‍රවාදය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයක පවතින සුවිශේෂී ලක්ෂණ 2ක් දක්වන්න.", 4, "1. නිදහස් හා සාධාරණ මැතිවරණ. 2. බහුතරයේ කැමැත්ත සහ සුළුතරයේ අයිතිවාසිකම් රැකීම.", listOf("ප්‍රජාතන්ත්‍රවාදී ලක්ෂණ (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "ප්‍රජාතන්ත්‍රවාදී සමාජයක මාධ්‍ය සතු වගකීම පැහැදිලි කරන්න.", 4, "සත්‍ය තොරතුරු ජනතාවට සැපයීම සහ රජයේ ක්‍රියාකලාපය විවේචනාත්මකව නිරීක්ෂණය කිරීම.", listOf("මාධ්‍ය වගකීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "පාසල් මට්ටමින් ප්‍රජාතන්ත්‍රවාදී අගයන් ප්‍රගුණ කළ හැකි අවස්ථාවක් ලියන්න.", 4, "ශිෂ්‍ය නායක මණ්ඩල තේරීම හෝ පන්ති නායකයන් පත් කිරීමේදී ඡන්දය භාවිත කිරීම.", listOf("පාසල් ප්‍රජාතන්ත්‍රවාදය (ලකුණු 4)"))
      )
      3 -> listOf(
